ssh sgs-gpu07 'cat > ~/variants2.cu << '"'"'EOF'"'"'
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <vector>
#include <algorithm>
typedef unsigned char uchar; typedef unsigned long long ull;
struct PagePlanDev { uchar* dst; const int* slot_base; };
constexpr size_t PS=64,H=8,D=128,ES=2;
constexpr size_t SB=H*D*ES, TB=2*SB, PB=PS*TB; constexpr int LAYERS=40;
// old
__global__ void oldk(const uchar* __restrict__ k,const uchar* __restrict__ v,const PagePlanDev* __restrict__ pages,int np,int ps,int sb,int ts,int upt,int ub,ull off){
  int p=blockIdx.y; if(p>=np)return; PagePlanDev pg=pages[p];
  ull u=(ull)blockIdx.x*blockDim.x+threadIdx.x; ull pu=(ull)ps*upt; if(u>=pu)return;
  int t=u/upt,ch=u%upt; int slot=pg.slot_base[t];
  ull o=(ull)ch*ub, so=(ull)slot*sb;
  const uchar* sk=k+so+o; const uchar* sv=v+so+o; uchar* dk=pg.dst+off+(ull)t*ts+o; uchar* dv=dk+sb;
  if(ub==16){*(uint4*)dk=*(const uint4*)sk;*(uint4*)dv=*(const uint4*)sv;} else{*dk=*sk;*dv=*sv;}
}
// new (lib)
__global__ void newk(const uchar* __restrict__ k,const uchar* __restrict__ v,const PagePlanDev* __restrict__ pages,int np,int ps,int sb,int ts,int upt,int ub,ull off){
  const long long pu=(long long)ps*upt; const long long us=(long long)gridDim.x*blockDim.x;
  for(int p=blockIdx.y;p<np;p+=gridDim.y){ const PagePlanDev pg=pages[p];
    for(long long u=(long long)blockIdx.x*blockDim.x+threadIdx.x;u<pu;u+=us){
      const int t=(int)(u/upt); const int ch=(int)(u-(long long)t*upt); const int slot=pg.slot_base[t];
      const long long o=(long long)ch*ub, so=(long long)slot*sb;
      const uchar* sk=k+so+o; const uchar* sv=v+so+o; uchar* dk=pg.dst+off+(long long)t*ts+o; uchar* dv=dk+sb;
      if(ub==16){*(uint4*)dk=*(const uint4*)sk;*(uint4*)dv=*(const uint4*)sv;} else{*dk=*sk;*dv=*sv;}
    }
  }
}
double med(std::vector<double> x){std::sort(x.begin(),x.end());return x[x.size()/2];}
int main(int argc,char**argv){
  int np=192; int which=atoi(argv[1]); cudaSetDevice(0);
  size_t ns=(size_t)np*PS; std::vector<uchar*> k(LAYERS),v(LAYERS);
  for(int l=0;l<LAYERS;l++){cudaMalloc(&k[l],ns*SB);cudaMalloc(&v[l],ns*SB);cudaMemset(k[l],l+1,ns*SB);cudaMemset(v[l],l+2,ns*SB);}
  std::vector<uchar*> pages(np); for(int p=0;p<np;p++)cudaMalloc(&pages[p],(size_t)LAYERS*PB);
  std::vector<int> slots(ns); for(size_t i=0;i<ns;i++)slots[i]=i;
  std::vector<PagePlanDev> hp(np); int* ds; cudaMalloc(&ds,ns*sizeof(int)); cudaMemcpy(ds,slots.data(),ns*sizeof(int),cudaMemcpyHostToDevice);
  for(int p=0;p<np;p++){hp[p].dst=pages[p];hp[p].slot_base=ds+p*PS;}
  PagePlanDev* dp; cudaMalloc(&dp,np*sizeof(PagePlanDev)); cudaMemcpy(dp,hp.data(),np*sizeof(PagePlanDev),cudaMemcpyHostToDevice);
  int upt=SB/16,ub=16; unsigned gxx=(PS*upt+255)/256;
  cudaStream_t s;cudaStreamCreate(&s);cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
  auto launch=[&](int l,cudaStream_t st){ull off=(ull)l*PB; if(which==0)oldk<<<dim3(gxx,np),256,0,st>>>(k[l],v[l],dp,np,PS,SB,TB,upt,ub,off); else newk<<<dim3(gxx,np),256,0,st>>>(k[l],v[l],dp,np,PS,SB,TB,upt,ub,off);};
  for(int i=0;i<5;i++)launch(i%LAYERS,s); cudaStreamSynchronize(s);
  std::vector<double> r; for(int i=0;i<50;i++){int l=i%LAYERS;cudaEventRecord(a,s);launch(l,s);cudaEventRecord(b,s);cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);r.push_back(ms*1000);}
  double m=med(r); printf("%s med %.2f us payload %.3f TB/s\n",which?"new":"old",m,(np*PB/1e9)/(m*1e-6));
  return 0;
}
